import { useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

type ReportDatePickerProps = {
  defaultValue?: Date | null;
  onChange?: (value: Date | null) => void;
};

const startOfDay = (date: Date) => new Date(date.getFullYear(), date.getMonth(), date.getDate());

const shiftDays = (days: number) => {
  const date = startOfDay(new Date());
  date.setDate(date.getDate() - days);
  return date;
};

const isSameDay = (a: Date | null, b: Date) =>
  a !== null && startOfDay(a).getTime() === b.getTime();

export default function ReportDatePicker({ defaultValue = null, onChange }: ReportDatePickerProps) {
  const [value, setValue] = useState<Date | null>(defaultValue);

  const presets = [
    { label: 'Сегодня', date: shiftDays(0) },
    { label: 'Вчера', date: shiftDays(1) },
    { label: 'Неделя назад', date: shiftDays(7) },
  ];

  const select = (next: Date | null) => {
    setValue(next);
    onChange?.(next);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
        {presets.map((preset) => (
          <JxChip
            key={preset.label}
            active={isSameDay(value, preset.date)}
            onClick={() => select(preset.date)}
          >
            {preset.label}
          </JxChip>
        ))}
      </div>
      <JxCalendar locale="ru-RU" value={value} onValueChange={select} />
    </div>
  );
}

